<script setup>
import { onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api } from '../services/api'
const route=useRoute();const router=useRouter();const tab=ref('basic');const saving=ref(false);const categories=ref([]);const error=ref('')
const form=ref({name:'',brand:'',sku:'',category_id:null,description:'',image_url:'',price:0,cost:0,discount:0,stock:0,threshold:5,weight:0,status:'DRAFT'})
const tabs=[['basic','Basic Info'],['media','Media'],['pricing','Pricing & Inventory']]
const isEdit=!!route.params.id
async function load(){try{const r=await api.categories();categories.value=r?.data||r||[]}catch{} if(isEdit){try{const r=await api.product(route.params.id);Object.assign(form.value,r?.data||r)}catch(e){error.value=e.message}}}
async function save(status=form.value.status){error.value='';if(!form.value.name||!form.value.category_id){error.value='Product name and category are required.';tab.value='basic';return} saving.value=true;try{const r=await api.saveProduct({...form.value,status},route.params.id);const product=r?.data||r;if(!isEdit&&product?.id)router.replace(`/products/${product.id}/edit`);else router.push('/products')}catch(e){error.value=e.message||'Unable to save product'}finally{saving.value=false}}
onMounted(load)
</script>
<template><div><div class="page-head"><div><span class="eyebrow">CATALOG / PRODUCTS</span><h1>{{isEdit?form.name||'Edit Product':'Add Product'}}</h1><p>Configure the product once; its category controls where it appears across the storefront.</p></div><div><RouterLink class="button button-ghost" to="/products">Discard</RouterLink><button class="button button-dark" :disabled="saving" @click="save('DRAFT')">Save as Draft</button><button class="button button-blue" :disabled="saving" @click="save('PUBLISHED')">{{saving?'Saving...':'Publish Product'}}</button></div></div><div class="editor-tabs"><button v-for="t in tabs" :key="t[0]" :class="{active:tab===t[0]}" @click="tab=t[0]">{{t[1]}}</button></div><div v-if="error" class="error-banner">{{error}}</div><section class="editor-grid"><div class="panel form-panel"><template v-if="tab==='basic'"><h2>General Information</h2><div class="form-grid"><label>Product Name *<input v-model="form.name" placeholder="55 inch Smart TV"></label><label>Brand<input v-model="form.brand" placeholder="Brand"></label><label>SKU / Model Code<input v-model="form.sku" placeholder="SKU-001"></label><label>Category *<select v-model="form.category_id"><option :value="null">Select a category</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label class="full-field">Description<textarea v-model="form.description"></textarea></label></div><h2>Publishing</h2><select v-model="form.status"><option value="DRAFT">Draft</option><option value="PUBLISHED">Published</option><option value="ARCHIVED">Archived</option></select></template><template v-else-if="tab==='media'"><h2>Product Photos</h2><label>Primary Image URL<input v-model="form.image_url" placeholder="https://images..."/></label><div class="preview"><img v-if="form.image_url" :src="form.image_url" :alt="form.name" class="editor-image"><span v-else>No image configured yet.</span></div></template><template v-else><h2>Pricing & Inventory</h2><div class="form-grid"><label>Price<input v-model.number="form.price" type="number" min="0"></label><label>Discount %<input v-model.number="form.discount" type="number" min="0" max="100"></label><label>Cost<input v-model.number="form.cost" type="number" min="0"></label><label>Stock Available<input v-model.number="form.stock" type="number" min="0"></label><label>Low Stock Threshold<input v-model.number="form.threshold" type="number" min="0"></label><label>Weight (kg)<input v-model.number="form.weight" type="number" min="0"></label></div></template></div><aside class="panel side-preview"><h3>Storefront Live Preview</h3><div class="preview-image"><img v-if="form.image_url" :src="form.image_url" :alt="form.name"/><div v-else class="device-shape"></div></div><b>{{form.name||'New product'}}</b><small>{{form.sku||'SKU'}}</small><strong>{{Number(form.price||0).toLocaleString()}} EGP</strong><span>{{form.stock||0}} in stock</span><span>Category: {{categories.find(c=>c.id===form.category_id)?.name||'Not selected'}}</span></aside></section></div></template>
